#include <stdio.h>
#include <stdbool.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int total_time[105] = {0};
    int last_r[105] = {0};
    bool waiting[105] = {false};
    bool participated[105] = {false};

    int current_time = 0;
    int time_to_advance = 1;
    bool first_event = true;

    for (int i = 0; i < n; i++) {
        char type;
        int x;
        scanf(" %c %d", &type, &x);

        if (type == 'T') {
            time_to_advance = x;
        } else {
            if (first_event) {
                first_event = false;
            } else {
                current_time += time_to_advance;
            }
            time_to_advance = 1;

            participated[x] = true;
            if (type == 'R') {
                last_r[x] = current_time;
                waiting[x] = true;
            } else if (type == 'E') {
                total_time[x] += (current_time - last_r[x]);
                waiting[x] = false;
            }
        }
    }

    for (int x = 1; x <= 100; x++) {
        if (participated[x]) {
            if (waiting[x]) {
                printf("%d -1\n", x);
            } else {
                printf("%d %d\n", x, total_time[x]);
            }
        }
    }

    return 0;
}
